package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.service.jobs.GenerationFlowService.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
class ReportSupplementCaptureRoutingTest {
 boolean mysql(){return false;}
 DailyReportSupplementInputTest daily;
 void setup()throws Exception{daily=new DailyReportSupplementInputTest(){@Override boolean mysql(){return ReportSupplementCaptureRoutingTest.this.mysql();}};daily.setup();}
 ReportInputCaptureService.Scope scope(){return new ReportInputCaptureService.Scope("report:daily:"+daily.day,2,Stage.DAILY_REPORT,daily.day);}
 Prepare command(ReportInputCaptureService.Captured value,boolean supplement){return new Prepare(value.scope().logicalKey(),value.scope().generation(),value.scope().stage(),value.scope().day(),null,value.dependencies(),List.of(),value.sourceProof().verifiedDependencyIds(),supplement,"a".repeat(64));}
 @Test void ActualDailyRoutingBindsGenerationTwoFullOriginalBodyAndReadonlySourceMode()throws Exception{setup();var unused=mock(ReportPeriodInputComponentService.class);var base=daily.h.data.nativeData().fixture().f();var router=new ReportInputCaptureService(daily.h.service,unused,base.tx);var value=router.captureSupplement(scope(),daily.cutoff);assertEquals(scope(),value.scope());assertEquals(daily.cutoff,value.cutoff());assertEquals(1,value.sourceProof().candidates().size());assertEquals(1,value.dependencies().size());assertEquals(value.sourceProof(),daily.h.rr(()->router.asReadonlySource(value).snapshot(command(value,true),daily.cutoff)));assertSame(value,daily.h.rr(()->router.verifyObserved(value)));assertThrows(RuntimeException.class,()->daily.h.rr(()->router.asReadonlySource(value).snapshot(command(value,false),daily.cutoff)));verifyNoInteractions(unused);assertEquals(2,base.sends);}
 @Test void ActualPeriodRoutingRetainsAllUnknownDatesAtTheExplicitNewCutoff(){var fixture=new ReportPeriodSupplementInputTest(){@Override boolean mysql(){return ReportSupplementCaptureRoutingTest.this.mysql();}};fixture.setup();var base=fixture.h.h.h.f;var unused=mock(DailyReportInputComponentService.class);var router=new ReportInputCaptureService(unused,fixture.h.service,base.tx);var day=ReportPeriodInputComponentTest.LAST;var scope=new ReportInputCaptureService.Scope("report:weekly:"+day,2,Stage.WEEKLY_REPORT,day);var cutoff=ReportPeriodInputComponentTest.CUTOFF.plusSeconds(7).plusNanos(1000);var value=router.captureSupplement(scope,cutoff);assertEquals(scope,value.scope());assertEquals(6,value.sourceProof().missingInputs().size());assertEquals(1,value.sourceProof().candidates().size());assertEquals(1,value.referenceTargetsByEvidence().size());assertSame(value,fixture.h.rr(()->router.verifyObserved(value)));assertEquals(value.sourceProof(),fixture.h.rr(()->router.asReadonlySource(value).snapshot(command(value,true),cutoff)));verifyNoInteractions(unused);assertEquals(1,base.sends);}
 @Test void InitialGenerationCannotUseExplicitRouterAndWrongCutoffOrCallerTransactionRejects()throws Exception{setup();var base=daily.h.data.nativeData().fixture().f();var router=new ReportInputCaptureService(daily.h.service,mock(ReportPeriodInputComponentService.class),base.tx);assertThrows(RuntimeException.class,()->router.captureSupplement(new ReportInputCaptureService.Scope("report:daily:"+daily.day,1,Stage.DAILY_REPORT,daily.day),daily.cutoff));assertThrows(RuntimeException.class,()->router.capture(scope(),daily.cutoff));assertThrows(RuntimeException.class,()->router.captureSupplement(scope(),daily.cutoff.plusNanos(1)));assertThrows(RuntimeException.class,()->daily.h.rr(()->router.captureSupplement(scope(),daily.cutoff)));var value=router.captureSupplement(scope(),daily.cutoff);assertThrows(RuntimeException.class,()->router.asReadonlySource(value).snapshot(command(value,true),daily.cutoff));assertThrows(RuntimeException.class,()->daily.h.rr(()->router.asReadonlySource(value).snapshot(command(value,true),daily.cutoff.plusNanos(1000))));}
 @Test void CapturedIssuerAndFullCurrentValidityMustStillMatchEveryNativeComponent()throws Exception{setup();var base=daily.h.data.nativeData().fixture().f();var period=mock(ReportPeriodInputComponentService.class);var router=new ReportInputCaptureService(daily.h.service,period,base.tx);var other=new ReportInputCaptureService(daily.h.service,period,base.tx);var value=router.captureSupplement(scope(),daily.cutoff);assertThrows(RuntimeException.class,()->daily.h.rr(()->other.verifyObserved(value)));base.jdbc.update("UPDATE contents SET state='blocked' WHERE id=?",daily.h.data.nativeData().completed().version().contentId());assertThrows(RuntimeException.class,()->daily.h.rr(()->router.verifyObserved(value)));assertTrue(router.captureSupplement(scope(),daily.cutoff).sourceProof().candidates().getFirst().evidence().blocked());}
}
